#!/bin/sh
/usr/sbin/update-ca-certificates > /dev/null 2>&1
exit 0

#!/bin/sh

dbus-send --system --type=method_call --dest=org.freedesktop.DBus / \
	org.freedesktop.DBUS.ReloadConfig >/dev/null 2>&1 || :

#!/bin/sh

for i in "$@"; do
	case "$i" in
	 # encodings dir doesn't include fonts
		*/encodings) continue;
	esac
	[ -d "$i" ] || continue
	rm -f "$i"/fonts.dir "$i"/fonts.scale
	rmdir "$i" 2>/dev/null || {
		mkfontdir "$i"
		mkfontscale "$i"
	}
done

#!/bin/sh

update-desktop-database -q
gtk-update-icon-cache -q -t -f usr/share/icons/hicolor
